(2,1,'2015-02-06 00:39:06','2015-02-06 00:39:06','[vc_row full_width=\"stretch_row\" parallax=\"content-moving\" parallax_image=\"18\" bg_style=\"stretch\" css=\".vc_custom_1489540138300{padding-top: 150px !important;padding-bottom: 150px !important;background-position: 0 0;background-repeat:-repeat;}\"][vc_column][vcex_heading text=\"SOLO NOS LIMITAN NUESTROS VALORES\" tag=\"h1\" text_align=\"center\" font_size=\"24px\" color=\"#ffffff\" css=\".vc_custom_1509143731644{margin-bottom: 5px !important;}\"][vcex_button url=\"http://injul.com.do/servicios/\" size=\"small\" title=\"Our Services\" style=\"flat\" align=\"center\" color=\"black\" text_transform=\"uppercase\" font_weight=\"600\" custom_background=\"#000000\" custom_hover_background=\"#565555\" border_radius=\"0px\" letter_spacing=\"2px\"]CONOCE MAS DE NUESTROS SERVICIOS[/vcex_button][/vc_column][/vc_row][vc_row center_row=\"yes\" padding_top=\"50px\" padding_bottom=\"35px\"][vc_column][vc_column_text responsive_text=\"true\" italic=\"true\" font_size=\"30px\" font_weight=\"bold\" css=\".vc_custom_1509143033415{margin-top: -10px !important;margin-bottom: -40px !important;}\"]\r\n<p style=\"text-align: center;\">Investigar es descubrir, descubrir es avanzar, avanzar es llegar a la verdad, que es nuestra meta.</p>\r\n[/vc_column_text][/vc_column][/vc_row][vc_row full_width=\"stretch_row\" column_spacing=\"40\" css=\".vc_custom_1489540145953{margin-bottom: 60px !important;padding-top: 60px !important;padding-bottom: 20px !important;background-color: #baa786 !important;}\"][vc_column width=\"1/2\" css=\".vc_custom_1451257286644{margin-top: 0px !important;}\"][vcex_image_flexslider slideshow=\"false\" direction_nav=\"false\" control_nav=\"false\" control_thumbs=\"false\" img_width=\"650\" img_height=\"260\" smooth_height=\"true\" image_ids=\"15\"][/vc_column][vc_column width=\"1/2\" css=\".vc_custom_1451257290931{margin-top: 0px !important;}\"][vcex_heading text=\"NUESTRA MISIÓN \" tag=\"h2\" font_size=\"18px\" col