=\"#ffffff\"][vcex_spacing size=\"20px\"][vc_column_text color=\"#ffffff\"]\n<p style=\"text-align: left;\">Convertirnos en la empresa líder a nivel nacional de las investigaciones jurídicas públicas o privadas, a través del desarrollo de las técnicas investigativas requeridas y las destrezas en la materia de nuestro personal.</p>\n[/vc_column_text][vcex_spacing][vcex_button url=\"http://totaltheme.wpengine.com/law-firm/services/\" target=\"blank\" size=\"small\" title=\"Our Services\" style=\"flat\" color=\"black\" text_transform=\"uppercase\" font_weight=\"600\" custom_background=\"#632032\" custom_hover_background=\"#4f1a2a\" border_radius=\"0px\" letter_spacing=\"2px\"]Conoce mas sobre nuestros servicios[/vcex_button][/vc_column][/vc_row][vc_row center_row=\"yes\" css=\".vc_custom_1451257205838{margin-bottom: 20px !important;}\"][vc_column][vcex_heading text=\"NO DUDE EN CONTACTARNOS\" tag=\"h1\" text_align=\"center\" font_size=\"21px\" color=\"#3e5da3\" css=\".vc_custom_1509976985232{margin-bottom: 5px !important;}\"][vcex_divider color=\"#632032\" width=\"2%\" height=\"3px\" icon_color=\"#000000\" icon_size=\"14px\" margin_top=\"10px\" margin_bottom=\"25px\"][vc_column_text font_size=\"16px\"]\n<p style=\"text-align: center;\">Tel.: 809-547-3178</p>\n<p style=\"text-align: center;\">Email: injul01@gmail.com</p>\n<p style=\"text-align: center;\">Rafael Augusto Sánchez No. 125, , Edif. Alexander, suite 104, Evaristo Morales, D.N</p>\n[/vc_column_text][/vc_column][/vc_row]','Home','','inherit','closed','closed','','2-autosave-v1','','','2021-05-31 13:11:07','2021-05-31 13:11:07','',2,'http://injul.com.do/2021/05/30/2-autosave-v1/',0,'revision','',0),
